import {PALETTE,BIOMES,SKILLS,createState,ensureFloor,biomeIndex,power,upgradeCost,windowMs,purchaseUpgrade,purchaseSkill,purchaseBase,hit,descend,newExpedition,restoreState} from './engine.js';
import {CaveArt} from './art.js';
import {Music,BEAT} from './audio.js';
const $=id=>document.getElementById(id),KEY='gemventure-save-v1';
let s;try{s=restoreState(localStorage.getItem(KEY));}catch{}s=s||createState();ensureFloor(s);
const canvas=$('cave'),art=new CaveArt(canvas),music=new Music();
let selected=s.nodes.find(n=>n.hp>0)?.id??0,combo=0,lastHit=-1000,lastPerfectBeat=-1,lastComboBeat=-1,lastAutoBeat=-1,paused=false,modalPaused=false,hiddenPaused=false,elapsed=0,lastFrame=performance.now(),toastTimer,feedbackUntil=0,modalTab='';
art.rebuild(s);
const format=n=>new Intl.NumberFormat('pt-BR').format(n);
const isPaused=()=>paused||modalPaused||hiddenPaused;
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));$('saveStatus').textContent='Progresso salvo localmente';}catch{$('saveStatus').textContent='Salvamento indisponível';}}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3000);}
function updateTarget(){const n=s.nodes.find(n=>n.id===selected);$('targetName').textContent=n?.hp>0?BIOMES[biomeIndex(s.floor)].gemName:'Todos os cristais coletados';$('targetHealth').style.width=n?`${n.hp/n.maxHp*100}%`:'0%';const width=windowMs(s)/1000/BEAT*50;document.querySelector('.rhythm-perfect').style.width=`${width}%`;document.querySelector('.rhythm-perfect').style.left=`${50-width/2}%`;}
function update(){const b=biomeIndex(s.floor),bio=BIOMES[b];$('gems').textContent=format(s.gems);$('essence').textContent=format(s.essence);$('depth').textContent=s.floor*25;$('best').textContent=s.best*25;$('biomeName').textContent=bio.name;$('floorName').textContent=`ANDAR ${String(s.floor).padStart(2,'0')} · ${bio.zone}`;$('floorBadge').textContent=`${String(s.floor).padStart(2,'0')} / 16`;$('regionBadge').textContent=bio.badge;$('seedLabel').textContent=`MUNDO ${s.seed.toString(16).slice(0,6).toUpperCase()}`;$('journey').innerHTML=BIOMES.map((x,i)=>`<div class="journey-stop ${i===b?'active':i<b?'visited':''}"><span class="journey-marker">${x.icon}</span><div><strong>${x.short}</strong><small>${x.range}</small>${i===b?'<span class="current-tag">VOCÊ ESTÁ AQUI</span>':''}</div></div>`).join('');$('levelTag').textContent=`NV. ${s.level}`;$('powerStat').textContent=power(s);$('critStat').textContent=s.skills.includes('resonance')?'×3':'×2';$('syncStat').textContent=`±${windowMs(s)} ms`;$('upgradeCost').textContent=format(upgradeCost(s));$('upgradeBtn').disabled=s.gems<upgradeCost(s);$('upgradeNote').textContent=s.gems<upgradeCost(s)?`Mais ${format(upgradeCost(s)-s.gems)} gemas para sua próxima melhoria.`:'Pronta para ficar ainda mais forte.';$('pickName').textContent=s.level<4?'Companheira de jornada':s.level<8?'Desbravadora de cristais':'Lenda das profundezas';$('pickRarity').textContent=s.level<4?'O começo de algo brilhante':s.level<8?'Forjada para ir além':'O coração da Terra está chamando';$('collection').textContent=s.collection.length;const cleared=s.nodes.filter(n=>n.hp===0).length;$('progressText').textContent=`${cleared} / 8 cristais`;$('floorProgress').style.width=`${cleared/8*100}%`;$('floorComplete').hidden=!s.claimed;$('completeTitle').textContent=s.floor===16?'O coração da Terra é seu!':'Caminho aberto!';$('completeText').textContent=s.floor===16?'16 andares. Quatro mundos. Uma picareta lendária.':'+1 essência conquistada. Qual será sua próxima descoberta?';$('nextFloor').innerHTML=s.floor===16?'Nova expedição <span>↻</span>':'Descer mais fundo <span>↓</span>';updateTarget();}
function mine(id,automatic=false){if(isPaused()||s.claimed)return;const now=performance.now();if(!automatic&&now-lastHit<160)return;const n=s.nodes.find(n=>n.id===id);if(!n||n.hp===0)return;if(!automatic)lastHit=now;selected=id;const beat=elapsed/BEAT,nearest=Math.round(beat),distance=Math.abs(beat-nearest)*BEAT*1000;const perfect=!automatic&&distance<=windowMs(s)&&nearest!==lastPerfectBeat;
 if(!automatic){if(perfect){combo=nearest-lastComboBeat<=2?combo+1:1;lastPerfectBeat=nearest;lastComboBeat=nearest;}else combo=0;}
 const result=hit(s,id,perfect,combo,automatic);art.burst(n,BIOMES[biomeIndex(s.floor)].gem[2],result.earned,perfect);music.hit(perfect);for(const other of result.destroyed.filter(x=>x!==id))art.burst(s.nodes[other],BIOMES[biomeIndex(s.floor)].gem[2],0,perfect);
 $('comboValue').textContent=combo>0?Math.min(2,1+combo*.05).toFixed(2).replace('.',','):'1';$('comboLabel').textContent=combo>0?`${combo} golpe${combo===1?'':'s'} perfeito${combo===1?'':'s'}`:'Encontre o ritmo';$('rhythmFeedback').textContent=automatic?'Eco da picareta · golpe automático':perfect?`PERFEITO! Dano ×${s.skills.includes('resonance')?3:2} · ${combo} em sequência`:'Bom golpe! Tente acertar o centro.';feedbackUntil=elapsed+2;$('canvasHint').textContent=automatic?'Sua picareta encontrou o próprio ritmo.':'↑ Continue no ritmo. Cada cristal esconde uma descoberta.';
 if(n.hp===0)selected=s.nodes.find(x=>x.hp>0)?.id??id;
 if(result.complete){music.reward();toast(s.floor===16?'Você alcançou o manto! Sua jornada virou lenda.':'Andar concluído! +1 essência para suas habilidades.');}
 update();save();}
canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;canvas.focus({preventScroll:true});const box=canvas.getBoundingClientRect();const x=(e.clientX-box.left)*960/box.width,y=(e.clientY-box.top)*540/box.height;const nodes=s.nodes.filter(n=>n.hp>0).map(n=>({n,d:Math.hypot((n.x-x),n.y-22-y)})).sort((a,b)=>a.d-b.d);if(nodes[0]&&nodes[0].d<95)mine(nodes[0].n.id);else if(x<108&&y>225&&y<365)openBase();else toast('Clique em um cristal brilhante ou pressione espaço.');});
document.addEventListener('keydown',e=>{if($('modal').open)return;if(e.code==='Space'&&(e.target===document.body||e.target===canvas)){e.preventDefault();if(!e.repeat)mine(selected);}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code)&&(e.target===canvas||e.target===document.body)){e.preventDefault();const alive=s.nodes.filter(n=>n.hp>0);if(!alive.length)return;const i=alive.findIndex(n=>n.id===selected);selected=alive[(i+(e.code==='ArrowLeft'||e.code==='ArrowUp'?-1:1)+alive.length)%alive.length].id;updateTarget();}if(e.code==='KeyP'&&!e.repeat&&e.target===canvas)togglePause();});
function next(){const final=s.floor===16;if(final?newExpedition(s):descend(s)){selected=0;combo=0;lastPerfectBeat=-1;lastComboBeat=-1;$('comboValue').textContent='1';$('comboLabel').textContent='Encontre o ritmo';art.rebuild(s);update();save();toast(final?'Um novo mundo. Todas as suas melhorias continuam com você.':`Andar ${s.floor} · ${BIOMES[biomeIndex(s.floor)].name}`);}}
$('nextFloor').onclick=next;$('completeBase').onclick=()=>openBase();
$('upgradeBtn').onclick=()=>{if(purchaseUpgrade(s)){update();save();music.reward();toast(`Picareta nível ${s.level}! Força de mineração: ${power(s)}.`);}};
$('soundBtn').onclick=async()=>{if(music.enabled){music.stop();$('soundText').textContent='Som desligado';$('soundBtn').setAttribute('aria-label','Ativar música');$('soundBtn').title='Ativar música';}else if(await music.enable()){$('soundText').textContent='Som ligado';$('soundBtn').setAttribute('aria-label','Desativar música');$('soundBtn').title='Desativar música';toast('Música ativada. Siga o pulso luminoso.');}else toast('Não foi possível ativar o áudio neste navegador.');};
function togglePause(){paused=!paused;music.silence();$('pauseBtn').textContent=paused?'▶':'Ⅱ';$('pauseBtn').setAttribute('aria-label',paused?'Continuar jogo':'Pausar jogo');$('rhythmFeedback').textContent=paused?'Em pausa. Continue quando quiser.':'Acerte no centro. Faça cada golpe valer.';}
$('pauseBtn').onclick=togglePause;
function openModal(eyebrow,content){modalPaused=true;music.silence();$('modalEyebrow').textContent=eyebrow;$('modalBody').innerHTML=content;if(!$('modal').open)$('modal').showModal();}
function closeModal(){$('modal').close();}
$('closeModal').onclick=closeModal;$('modal').addEventListener('close',()=>{modalPaused=false;modalTab='';lastFrame=performance.now();canvas.focus({preventScroll:true});});$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function openBase(tab='base'){modalTab=tab;const tabs=`<div class="modal-tabs"><button data-tab="base" class="${tab==='base'?'active':''}">Sua base</button><button data-tab="skills" class="${tab==='skills'?'active':''}">Árvore de habilidades</button></div>`;let content='';if(tab==='base')content=`<div class="base-upgrades"><div class="skill-card"><span class="skill-icon">⚒</span><strong>Forja de cristal</strong><p>Uma bancada melhor para sua única ferramenta. Todas as melhorias da picareta custam 20% menos.</p><button class="${s.base.forge?'secondary':'primary'}" data-base="forge" ${s.base.forge||s.gems<80?'disabled':''}>${s.base.forge?'✓ Construída':'Construir · 80 gemas'}</button></div><div class="skill-card"><span class="skill-icon">◉</span><strong>Farol de ressonância</strong><p>O pulso da base acompanha você. Ganhe mais 20 ms na janela de sincronia em todos os andares.</p><button class="${s.base.beacon?'secondary':'primary'}" data-base="beacon" ${s.base.beacon||s.gems<60?'disabled':''}>${s.base.beacon?'✓ Aceso':'Acender · 60 gemas'}</button></div></div>`;else content=`<div class="skill-grid">${['SINCRONIA','DESCOBERTA','POTÊNCIA'].map((name,i)=>`<div class="skill-branch"><div class="branch-title">${name}</div>${SKILLS.filter(k=>k.branch===i).map(k=>{const owned=s.skills.includes(k.id),locked=k.requires&&!s.skills.includes(k.requires);return`<div class="skill-card ${owned?'owned':''}"><span class="skill-icon">${k.icon}</span><strong>${k.name}</strong><p>${k.desc}</p><button class="${owned?'secondary':'primary'}" data-skill="${k.id}" ${owned||locked||s.essence<k.cost?'disabled':''}>${owned?'✓ Desbloqueada':locked?'↑ Libere a anterior':`Aprender · ${k.cost} essência${k.cost>1?'s':''}`}</button></div>`;}).join('')}</div>`).join('')}</div>`;
 openModal('ACAMPAMENTO DA SUPERFÍCIE',`<h2>${tab==='base'?'Seu lugar para ir mais longe.':'Sua picareta. Seu caminho.'}</h2><p>${tab==='base'?'O elevador guarda seu progresso. Prepare-se para a próxima descida.':'Cada andar completo rende uma essência. Escolha como quer evoluir.'}</p>${tabs}${content}<div class="modal-footer"><span>◇ ${format(s.gems)} gemas &nbsp; ✦ ${s.essence} essências</span><button class="primary" id="resumeMine">${s.claimed?(s.floor===16?'Nova expedição ↻':'Próximo andar ↓'):'Voltar à mineração ↓'}</button></div>`);
 $('modalBody').querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>openBase(b.dataset.tab));$('modalBody').querySelectorAll('[data-base]').forEach(b=>b.onclick=()=>{if(purchaseBase(s,b.dataset.base)){save();update();openBase('base');music.reward();toast('Melhoria da base construída!');}});$('modalBody').querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{if(purchaseSkill(s,b.dataset.skill)){save();update();openBase('skills');music.reward();toast('Habilidade desbloqueada!');}});$('resumeMine').onclick=()=>{closeModal();if(s.claimed)next();};
}
$('baseBtn').onclick=()=>openBase();$('talentsBtn').onclick=()=>openBase('skills');
$('helpBtn').onclick=()=>{openModal('GUIA DO EXPLORADOR',`<h2>Uma batida. Um novo brilho.</h2><p>Uma pequena expedição de mineração, música e descobertas.</p><div class="help-steps"><div><b>01 · Encontre seu cristal</b><p>Clique nos cristais luminosos. Cada golpe reduz sua resistência e, ao quebrar, você coleta gemas.</p></div><div><b>02 · Acerte o ritmo</b><p>Quando um losango passa pelo centro da barra, seu golpe fica perfeito: mais dano, mais gemas e sequência.</p></div><div><b>03 · Desça ou volte</b><p>Quebre os 8 cristais para liberar o elevador. Siga ao próximo andar ou visite a base. Você pode subir antes e continuar depois.</p></div><div><b>04 · Evolua sua picareta</b><p>Gemas aumentam a força. Essências liberam habilidades. A jornada passa por 4 biomas até chegar ao manto, no andar 16.</p></div></div><div class="help-controls"><span><kbd>ESPAÇO</kbd> minerar</span><span><kbd>← →</kbd> escolher cristal</span><span><kbd>P</kbd> pausar com a caverna selecionada</span></div><p>Ative ♫ no topo para ouvir a trilha. O progresso é salvo neste navegador. As profundidades fazem parte de um mundo de fantasia.</p><button class="primary" id="helpDone">Vamos explorar ↓</button>`);$('helpDone').onclick=closeModal;};
$('newWorld').onclick=()=>{openModal('ATLAS DAS PROFUNDEZAS',`<h2>Há um mundo lá embaixo.</h2><p>Expedição ${s.run} · 16 andares gerados a partir da sua semente. Cada nova expedição cria novas cavernas e mantém suas melhorias.</p><div class="biome-list">${BIOMES.map((b,i)=>`<div><strong style="color:${b.gem[2]}">${b.icon} ${b.short}</strong><small>Andares ${i*4+1}–${i*4+4} · ${s.collection.includes(i)?'Gema descoberta':'Descoberta à sua espera'}</small></div>`).join('')}</div><div class="swatches" aria-label="32 cores da paleta AREN32">${PALETTE.map(c=>`<i style="background:${c}"></i>`).join('')}</div><p>Arte procedural com a paleta AREN32, de ArenSpace. ${format(s.totalGems)} gemas coletadas · ${s.totalPerfect} golpes perfeitos.</p>`);};
document.addEventListener('visibilitychange',()=>{hiddenPaused=document.hidden;music.silence();lastFrame=performance.now();save();});window.addEventListener('pagehide',save);
function frame(now){const delta=Math.min((now-lastFrame)/1000,.05);lastFrame=now;if(!isPaused()){elapsed+=delta;music.update(elapsed,biomeIndex(s.floor));const beat=Math.floor(elapsed/BEAT);if(s.skills.includes('echo')&&!s.claimed&&beat%4===0&&beat!==lastAutoBeat){lastAutoBeat=beat;mine(s.nodes.find(n=>n.hp>0)?.id,true);}if(combo&&elapsed/BEAT-lastComboBeat>2.5){combo=0;$('comboValue').textContent='1';$('comboLabel').textContent='Encontre o ritmo';}}
 const phase=elapsed/BEAT;for(let i=0;i<5;i++){$('note'+i).style.left=`${50+(Math.floor(phase)+i-2-phase)*25}%`;}$('beatLight').style.opacity=Math.abs(phase-Math.round(phase))<.13?'1':'.25';if(elapsed>feedbackUntil&&!paused)$('rhythmFeedback').textContent='Acerte no centro. Faça cada golpe valer.';art.draw(now,s,selected,isPaused());requestAnimationFrame(frame);}
update();save();requestAnimationFrame(frame);
